class Solution:
    def largestPerimeter(self, nums: list[int]) -> int:
        nums.sort()
        prefix = sum(nums)
        for i in range(len(nums) - 1, 1, -1):
            prefix -= nums[i]
            if nums[i] < prefix:
                return prefix + nums[i]
        return -1

